/**
 * 集成测试: CLI reportsDir → summary.json / plan report.json
 */

import * as fs from 'fs';
import * as os from 'os';
import * as path from 'path';

import { beforeEach, describe, expect, it, vi } from 'vite-plus/test';

import { runTestExecution } from '../../src/commands/test-execution';
import type { ExecutionResult } from '../../src/lib/test-runner';
import type { TestPlan } from '../../src/schemas';

const mockDetectFrameworks = vi.fn();
const mockExecutePlanEntry = vi.fn();

vi.mock('../../src/commands/test-detect-frameworks', () => ({
  runTestDetectFrameworks: (...args: unknown[]) => mockDetectFrameworks(...args),
}));

vi.mock('../../src/lib/test-runner', () => ({
  executePlanEntry: (...args: unknown[]) => mockExecutePlanEntry(...args),
}));

function createTempProject(): { root: string; cleanup: () => void } {
  const root = fs.mkdtempSync(path.join(os.tmpdir(), 'cli-test-execution-'));
  fs.mkdirSync(path.join(root, 'openspec'), { recursive: true });
  fs.writeFileSync(
    path.join(root, 'openspec', 'config.json'),
    JSON.stringify({ schema: 'spec-driven', tests: [{ root: '.', framework: 'vitest' }] }),
    'utf-8',
  );
  return { root, cleanup: () => fs.rmSync(root, { recursive: true, force: true }) };
}

function makePlan(overrides: Partial<TestPlan> = {}): TestPlan {
  return {
    cwd: '.',
    root: '.',
    framework: 'vitest',
    coverage_format: 'istanbul',
    coverage_output: 'coverage-summary.json',
    mutation_cwd: '.',
    mutation_script: null,
    script: {
      shell: 'npx vitest run --outputFile={results_file} {files}',
      cmd: 'npx vitest run --outputFile={results_file} {files}',
    },
    ...overrides,
  };
}

function makeResult(overrides: Partial<ExecutionResult> = {}): ExecutionResult {
  return {
    framework: 'vitest',
    exitCode: 0,
    testCases: [{ name: 't1', status: 'passed', durationMs: 10 }],
    coverage: null,
    mutation: null,
    durationMs: 100,
    testFiles: ['a.test.ts'],
    sourceFiles: ['a.ts'],
    planId: 'vitest',
    reportDir: '',
    ...overrides,
  };
}

describe('CLI 新报告布局 — 无 change', () => {
  beforeEach(() => {
    mockDetectFrameworks.mockReset();
    mockExecutePlanEntry.mockReset();
    vi.spyOn(console, 'log').mockImplementation(() => {});
  });

  it('无 change：写入 reports/test/summary.json 与 reports/test/vitest/report.json', async () => {
    const project = createTempProject();
    try {
      mockDetectFrameworks.mockReturnValue({ detected: [], plan: [makePlan()] });
      mockExecutePlanEntry.mockImplementation((_entry, _projectRoot, options) => {
        const reportDir = path.join(options.reportsDir, 'vitest');
        return makeResult({ reportDir, planId: 'vitest' });
      });

      const exitCode = await runTestExecution({ projectRoot: project.root });
      expect(exitCode).toBe(0);

      const summaryPath = path.join(project.root, 'reports', 'test', 'summary.json');
      const reportPath = path.join(project.root, 'reports', 'test', 'vitest', 'report.json');
      expect(fs.existsSync(summaryPath)).toBe(true);
      expect(fs.existsSync(reportPath)).toBe(true);
      expect(fs.existsSync(path.join(project.root, 'reports', 'test-execution.json'))).toBe(false);
      expect(fs.existsSync(path.join(project.root, 'reports', 'test', 'vitest.json'))).toBe(false);

      const summary = JSON.parse(fs.readFileSync(summaryPath, 'utf-8'));
      expect(Array.isArray(summary.plans)).toBe(true);
      expect(summary.plans[0].id).toBe('vitest');
      expect(summary.plans[0].path.replace(/\\/g, '/')).toMatch(/reports\/test\/vitest$/);
    } finally {
      project.cleanup();
    }
  });

  it('execute 半失败仍写 report.json，summary.plans 含该 plan 的 path', async () => {
    const project = createTempProject();
    try {
      mockDetectFrameworks.mockReturnValue({ detected: [], plan: [makePlan()] });
      mockExecutePlanEntry.mockImplementation((_e, _r, options) =>
        makeResult({
          exitCode: 1,
          error: 'failed',
          testCases: [{ name: 't', status: 'failed', errorMessage: 'x' }],
          reportDir: path.join(options.reportsDir, 'vitest'),
        }),
      );

      const exitCode = await runTestExecution({ projectRoot: project.root });
      expect(exitCode).toBe(1);
      const summary = JSON.parse(
        fs.readFileSync(path.join(project.root, 'reports', 'test', 'summary.json'), 'utf-8'),
      );
      expect(summary.plans).toHaveLength(1);
      expect(summary.plans[0].path.replace(/\\/g, '/')).toContain('reports/test/vitest');
      expect(
        fs.existsSync(path.join(project.root, 'reports', 'test', 'vitest', 'report.json')),
      ).toBe(true);
    } finally {
      project.cleanup();
    }
  });

  it('多 directory plan：plugins_dev-team_bin_vite-plus/report.json 目录 id 无 .json', async () => {
    const project = createTempProject();
    try {
      mockDetectFrameworks.mockReturnValue({
        detected: [],
        plan: [
          makePlan(),
          makePlan({
            cwd: 'plugins/dev-team/bin',
            root: 'plugins/dev-team/bin',
            framework: 'vite-plus',
            coverage_format: 'istanbul',
          }),
        ],
      });
      mockExecutePlanEntry.mockImplementation((entry, _r, options) => {
        const planId =
          entry.root === '.'
            ? entry.framework
            : `${entry.root.replace(/[\\/]/g, '_')}_${entry.framework}`;
        return makeResult({
          framework: entry.framework,
          planId,
          reportDir: path.join(options.reportsDir, planId),
        });
      });

      await runTestExecution({ projectRoot: project.root });
      const nested = path.join(
        project.root,
        'reports',
        'test',
        'plugins_dev-team_bin_vite-plus',
        'report.json',
      );
      expect(fs.existsSync(nested)).toBe(true);
      const summary = JSON.parse(
        fs.readFileSync(path.join(project.root, 'reports', 'test', 'summary.json'), 'utf-8'),
      );
      expect(
        summary.plans.some((p: { id: string }) => p.id === 'plugins_dev-team_bin_vite-plus'),
      ).toBe(true);
    } finally {
      project.cleanup();
    }
  });
});

describe('CLI 新报告布局 — 有 change', () => {
  beforeEach(() => {
    mockDetectFrameworks.mockReset();
    mockExecutePlanEntry.mockReset();
    vi.spyOn(console, 'log').mockImplementation(() => {});
  });

  it('change 专属 …/reports/test/summary.json；plans[].path 含前缀', async () => {
    const project = createTempProject();
    try {
      // --change 现在兼作突变 scope 入口：读取 change 文件清单（清单为空 scope）
      const changeDir = path.join(project.root, 'openspec', 'changes', 'foo');
      fs.mkdirSync(changeDir, { recursive: true });
      fs.writeFileSync(
        path.join(changeDir, 'workflow.json'),
        JSON.stringify({
          workflow_type: 'requirement',
          created: '2026-09-17',
          files: { written: [], deleted: [] },
        }),
        'utf-8',
      );
      mockDetectFrameworks.mockReturnValue({ detected: [], plan: [makePlan()] });
      mockExecutePlanEntry.mockImplementation((_e, _r, options) =>
        makeResult({ reportDir: path.join(options.reportsDir, 'vitest') }),
      );
      await runTestExecution({ projectRoot: project.root, change: 'foo' });
      const summaryPath = path.join(
        project.root,
        'openspec',
        'changes',
        'foo',
        'reports',
        'test',
        'summary.json',
      );
      expect(fs.existsSync(summaryPath)).toBe(true);
      const summary = JSON.parse(fs.readFileSync(summaryPath, 'utf-8'));
      expect(summary.plans[0].path.replace(/\\/g, '/')).toMatch(
        /^openspec\/changes\/foo\/reports\/test\//,
      );
    } finally {
      project.cleanup();
    }
  });

  it('change 名含特殊字符时路径仍可创建或被拒绝', async () => {
    const project = createTempProject();
    const changeName = 'my-change.v2 with spaces';
    try {
      mockDetectFrameworks.mockReturnValue({ detected: [], plan: [makePlan()] });
      mockExecutePlanEntry.mockImplementation((_e, _r, options) =>
        makeResult({ reportDir: path.join(options.reportsDir, 'vitest') }),
      );

      let created = false;
      let rejected = false;
      try {
        const exitCode = await runTestExecution({
          projectRoot: project.root,
          change: changeName,
        });
        const summaryPath = path.join(
          project.root,
          'openspec',
          'changes',
          changeName,
          'reports',
          'test',
          'summary.json',
        );
        if (fs.existsSync(summaryPath) && exitCode === 0) {
          created = true;
          const summary = JSON.parse(fs.readFileSync(summaryPath, 'utf-8'));
          const planPath = String(summary.plans[0].path).replace(/\\/g, '/');
          expect(planPath).toContain(`openspec/changes/${changeName}/reports/test/`);
        } else {
          rejected = true;
        }
      } catch {
        rejected = true;
      }

      // 与现实现一致：要么成功落盘（含特殊字符路径），要么被拒绝
      expect(created || rejected).toBe(true);
    } finally {
      project.cleanup();
    }
  });
});

bin/__tests__/inventory-backtrack-preser.source:
/**
 * 集成测试: backtrack → workflow.json.files 保持不变（清单中立）
 *
 * 在真实临时工程上调用 runBacktrack（eval-json / file-inventory / phase 表全部
 * 真实实现，不 mock），验证清单中立语义：
 * - 任意回溯目标（implement / proposal / test-gen）→ files 逐项不变（含 source 审计映射）；
 * - files 缺失的机制前旧 change → 回溯成功（backtrack 不消费清单，不静默补建）；
 * - test-only 工作流（phase 表无 implement）→ 回溯成功且清单不变；
 * - 回溯后记录器可在原净状态上继续折叠（readFileInventory 重读原样）。
 *
 * @see openspec/specs/workflow-file-inventory/spec.md —「backtrack 保持清单，遗留由 redo 轮对冲」
 */

import * as fs from 'fs';
import * as os from 'os';
import * as path from 'path';

import { afterEach, beforeEach, describe, expect, it, vi } from 'vite-plus/test';

import { runBacktrack } from '../../src/commands/backtrack';
import { type EvalEntry } from '../../src/lib/eval-json';
import { readFileInventory } from '../../src/modules/workflow';

const CHANGE = 'inventory-change';

// runBacktrack 的 project_root 显式传入；但 getWorkflowType(change) 内部经
// getProjectDir() 解析工程根，优先级为 call-scoped → CLAUDE_PROJECT_DIR →
// WORKSPACE_FOLDER_PATHS → process.cwd()。这里通过 CLAUDE_PROJECT_DIR 把真实
// 解析链指向临时工程根：不 mock 任何模块，也不用 process.chdir（Stryker 的
// vitest runner 强制 worker 线程池，worker 中 process.chdir 会抛
// ERR_WORKER_UNSUPPORTED_OPERATION，与 eval-store-persist.test.ts 相同的约束）。
const ENV_KEYS = ['CLAUDE_PROJECT_DIR', 'WORKSPACE_FOLDER_PATHS'] as const;

let projectRoot: string;
let changeDir: string;
let savedEnv: Record<(typeof ENV_KEYS)[number], string | undefined>;

beforeEach(() => {
  savedEnv = {
    CLAUDE_PROJECT_DIR: process.env.CLAUDE_PROJECT_DIR,
    WORKSPACE_FOLDER_PATHS: process.env.WORKSPACE_FOLDER_PATHS,
  };
  projectRoot = fs.mkdtempSync(path.join(os.tmpdir(), 'inventory-backtrack-preserve-'));
  changeDir = path.join(projectRoot, 'openspec', 'changes', CHANGE);
  fs.mkdirSync(changeDir, { recursive: true });
  vi.stubEnv('CLAUDE_PROJECT_DIR', projectRoot);
  vi.stubEnv('WORKSPACE_FOLDER_PATHS', '');
});

afterEach(() => {
  vi.unstubAllEnvs();
  for (const key of ENV_KEYS) {
    if (savedEnv[key] === undefined) {
      delete process.env[key];
    } else {
      process.env[key] = savedEnv[key];
    }
  }
  fs.rmSync(projectRoot, { recursive: true, force: true });
});

const INVENTORY_WITH_SOURCE = {
  written: ['src/a.ts'],
  deleted: ['src/b.ts'],
  source: { 'src/a.ts': 'dev-team:implementation-generator' },
};

function makeEntry(
  overrides: Partial<EvalEntry> & Pick<EvalEntry, 'phase' | 'verdict'>,
): EvalEntry {
  return {
    attempt: 1,
    timestamp: '2026-09-17T00:00:00.000Z',
    report: 'r',
    checklist: [{ item: 'i', pass: true, evidence: 'e' }],
    backtrack_to: null,
    ...overrides,
  };
}

/** requirement 工作流的三条条目：proposal pass、implement pass、test-execution fail。 */
function requirementEntries(): EvalEntry[] {
  return [
    makeEntry({ phase: 'proposal', verdict: 'pass', timestamp: '2026-09-17T00:00:01.000Z' }),
    makeEntry({ phase: 'implement', verdict: 'pass', timestamp: '2026-09-17T00:00:03.000Z' }),
    makeEntry({ phase: 'test-execution', verdict: 'fail', timestamp: '2026-09-17T00:00:05.000Z' }),
  ];
}

function writeWorkflowJson(options: {
  workflowType: string;
  entries: EvalEntry[];
  files?: Record<string, unknown>;
}): void {
  const doc: Record<string, unknown> = {
    workflow_type: options.workflowType,
    created: '2026-09-17',
    ...(options.files !== undefined ? { files: options.files } : {}),
    eval: options.entries,
  };
  fs.writeFileSync(
    path.join(changeDir, 'workflow.json'),
    `${JSON.stringify(doc, null, 2)}\n`,
    'utf-8',
  );
}

function readWorkflowJson(): Record<string, unknown> {
  return JSON.parse(fs.readFileSync(path.join(changeDir, 'workflow.json'), 'utf-8')) as Record<
    string,
    unknown
  >;
}

function readEval(doc: Record<string, unknown>): Array<Record<string, unknown>> {
  return doc.eval as Array<Record<string, unknown>>;
}

function entryOfPhase(doc: Record<string, unknown>, phase: string): Record<string, unknown> {
  const found = readEval(doc).find((e) => e.phase === phase);
  expect(found).toBeDefined();
  return found!;
}

function backtrackTo(target: string): Parameters<typeof runBacktrack>[0] {
  return {
    project_root: projectRoot,
    change: CHANGE,
    phase: 'test-execution',
    backtrack_to: target,
    backtrack_reason: `回溯到 ${target}`,
  };
}

describe('backtrack → workflow.json.files 保持不变（清单中立）', () => {
  it('正向：回溯目标恰为 implement（等号语义）→ eval 条目写入 backtrack_to 且 implement 标 stale，files 逐项不变（含 source 键）', () => {
    writeWorkflowJson({
      workflowType: 'requirement',
      files: INVENTORY_WITH_SOURCE,
      entries: requirementEntries(),
    });

    const result = runBacktrack(backtrackTo('implement'));

    expect(result).toEqual({ modified: true, phase: 'test-execution', target: 'implement' });
    const doc = readWorkflowJson();
    const execution = entryOfPhase(doc, 'test-execution');
    expect(execution.backtrack_to).toBe('implement');
    expect(execution.backtrack_reason).toBe('回溯到 implement');
    // 下游（含被回溯的 test-execution 本身）随 implement 传播 stale
    expect(execution.stale).toBe(true);
    expect(entryOfPhase(doc, 'implement').stale).toBe(true);
    expect(doc.files).toEqual(INVENTORY_WITH_SOURCE);
    expect((doc.files as { source?: unknown }).source).toEqual(INVENTORY_WITH_SOURCE.source);
  });

  it('正向：回溯到 implement 之前的 phase（proposal）→ files 同样逐项不变', () => {
    writeWorkflowJson({
      workflowType: 'requirement',
      files: INVENTORY_WITH_SOURCE,
      entries: requirementEntries(),
    });

    const result = runBacktrack(backtrackTo('proposal'));

    expect(result).toEqual({ modified: true, phase: 'test-execution', target: 'proposal' });
    const doc = readWorkflowJson();
    expect(entryOfPhase(doc, 'proposal').stale).toBe(true);
    expect(doc.files).toEqual(INVENTORY_WITH_SOURCE);
    expect((doc.files as { source?: unknown }).source).toEqual(INVENTORY_WITH_SOURCE.source);
  });

  it('正向：回溯到 implement 之后的 phase（test-gen）→ files 保持原内容不清空', () => {
    writeWorkflowJson({
      workflowType: 'requirement',
      files: INVENTORY_WITH_SOURCE,
      entries: requirementEntries(),
    });

    const result = runBacktrack(backtrackTo('test-gen'));

    expect(result).toEqual({ modified: true, phase: 'test-execution', target: 'test-gen' });
    const doc = readWorkflowJson();
    expect(entryOfPhase(doc, 'test-execution').backtrack_to).toBe('test-gen');
    expect(doc.files).toEqual(INVENTORY_WITH_SOURCE);
    expect((doc.files as { source?: unknown }).source).toEqual(INVENTORY_WITH_SOURCE.source);
  });

  it('边界：机制前旧 change（无 files）→ 回溯成功（不消费清单），eval 正常改写且 MUST NOT 静默补建 files', () => {
    writeWorkflowJson({ workflowType: 'requirement', entries: requirementEntries() });

    const result = runBacktrack(backtrackTo('implement'));

    expect(result).toEqual({ modified: true, phase: 'test-execution', target: 'implement' });
    const doc = readWorkflowJson();
    expect(entryOfPhase(doc, 'test-execution').backtrack_to).toBe('implement');
    expect(Object.hasOwn(doc, 'files')).toBe(false);
  });

  it('边界：test-only 工作流（phase 表无 implement）回溯成功且 files 不变', () => {
    const files = { written: ['src/gen.ts'], deleted: [] };
    writeWorkflowJson({
      workflowType: 'test-only',
      files,
      entries: [
        makeEntry({
          phase: 'code-analyze',
          verdict: 'pass',
          timestamp: '2026-09-17T00:00:01.000Z',
        }),
        makeEntry({
          phase: 'test-execution',
          verdict: 'fail',
          timestamp: '2026-09-17T00:00:02.000Z',
        }),
      ],
    });

    const result = runBacktrack(backtrackTo('test-gen'));

    expect(result).toEqual({ modified: true, phase: 'test-execution', target: 'test-gen' });
    const doc = readWorkflowJson();
    expect(entryOfPhase(doc, 'test-execution').backtrack_to).toBe('test-gen');
    expect(doc.files).toEqual(files);
  });

  it('正向：回溯后 readFileInventory 重读 → 返回原净状态（记录器在原净状态上继续折叠的前置通路）', () => {
    writeWorkflowJson({
      workflowType: 'requirement',
      files: INVENTORY_WITH_SOURCE,
      entries: requirementEntries(),
    });

    runBacktrack(backtrackTo('implement'));

    expect(readFileInventory(changeDir)).toEqual(INVENTORY_WITH_SOURCE);
  });
});

